let execa: any
try {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  execa = require('execa')
} catch (err) {
  execa = {
    sync: (file: string, args: string[], options: any) => {
      const result = childProcess.spawnSync(file, args, options)
      const stderrStr = result.stderr ? result.stderr.toString() : ''
      const stdoutStr = result.stdout ? result.stdout.toString() : ''

      const returnedResult = {
        ...result,
        stdout: stdoutStr,
        stderr: stderrStr || (result.error ? result.error.message : null) || (result.status !== 0 ? `Process exited with code ${result.status}` : null),
        exitCode: result.status,
        failed: result.status !== 0 || !!result.error,
      }

      if (returnedResult.failed && options.reject !== false) {
        const error = new Error(returnedResult.stderr || 'Command failed')
        Object.assign(error, returnedResult)
        throw error
      }

      return returnedResult
    },
  }
}

